import unittest

from solution import merge_identity


class MergeIdentityTests(unittest.TestCase):
    def test_existing_account_updates_only_email_and_deep_copies(self):
        nested = {"roles": ["reader"], "prefs": {"theme": "dark"}}
        directory = {
            "key-1": {
                "username": "original-user",
                "email": "old@example.com",
                "password": "old-secret",
                "metadata": nested,
            },
            "other": {
                "username": "other",
                "email": "other@example.com",
                "password": "pw",
                "tags": ["x"],
            },
        }
        payload = {"external_key": "key-1", "email": "new@example.com", "secret": "unused"}
        result, account = merge_identity(directory, payload)
        self.assertIsNot(result, directory)
        self.assertIs(account, result["key-1"])
        self.assertEqual(account["username"], "original-user")
        self.assertEqual(account["email"], "new@example.com")
        self.assertEqual(account["password"], "old-secret")
        self.assertEqual(account["metadata"], nested)
        self.assertEqual(directory["key-1"]["email"], "old@example.com")
        self.assertIsNot(account, directory["key-1"])
        self.assertIsNot(account["metadata"], nested)
        self.assertIsNot(account["metadata"]["roles"], nested["roles"])
        self.assertIsNot(result["other"]["tags"], directory["other"]["tags"])
        account["metadata"]["roles"].append("writer")
        self.assertEqual(nested["roles"], ["reader"])
        directory["other"]["tags"].append("y")
        self.assertEqual(result["other"]["tags"], ["x"])

    def test_new_account_and_exact_return_identity(self):
        directory = {}
        payload = {"external_key": "new", "email": "n@example.com", "secret": "secret"}
        result, account = merge_identity(directory, payload)
        self.assertEqual(result, {
            "new": {"username": "new", "email": "n@example.com", "password": "secret"}
        })
        self.assertIs(account, result["new"])
        self.assertEqual(directory, {})
        self.assertEqual(payload, {"external_key": "new", "email": "n@example.com", "secret": "secret"})

    def test_payload_must_be_exact_and_nonempty_strings(self):
        valid_directory = {}
        payloads = [
            {},
            {"external_key": "k", "email": "e"},
            {"external_key": "k", "email": "e", "secret": "s", "extra": "x"},
            {"external_key": "", "email": "e", "secret": "s"},
            {"external_key": "k", "email": "", "secret": "s"},
            {"external_key": "k", "email": "e", "secret": ""},
            {"external_key": "k", "email": 3, "secret": "s"},
        ]
        for payload in payloads:
            with self.subTest(payload=payload), self.assertRaises((TypeError, ValueError)):
                merge_identity(valid_directory, payload)
        with self.assertRaises(TypeError):
            merge_identity(valid_directory, [])

    def test_malformed_directory_rejected(self):
        payload = {"external_key": "k", "email": "e", "secret": "s"}
        directories = [
            [],
            {1: {"username": "u", "email": "e", "password": "p"}},
            {"k": []},
            {"k": {"username": "u", "email": "e"}},
            {"k": {"username": "u", "password": "p"}},
            {"k": {"email": "e", "password": "p"}},
        ]
        for directory in directories:
            with self.subTest(directory=directory), self.assertRaises((TypeError, ValueError)):
                merge_identity(directory, payload)


if __name__ == "__main__":
    unittest.main()

